WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('MONTH', started_at) AS activity_month, AVG(session_no) AS avg_session_no, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, MIN(started_at) AS first_started_at, SUM(CASE WHEN device = 'desktop' THEN session_no ELSE 0 END) AS desktop_session_no, ROUND(AVG(is_new_burst), 2) AS avg_is_new_burst FROM sessionized GROUP BY DATE_TRUNC('MONTH', started_at) ORDER BY avg_session_no;
